users = boundary retry 2 {
    return list_users({})
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
assert(users != [], "no users returned")

days = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]
times = list.range(540, 961, 30)   # 09:00..16:00 in minutes, 30-min boundaries

per_user = for u in users {
    per_day = for d in days {
        a = boundary retry 2 {
            return get_availability({ user_id: u.id, date: d })
        } catch err {
            return fail("AVAIL_FAILED", err.code + ": " + err.message)
        }
        return { day: d, busy: a.busy if a.busy != null else [] }
    }
    return { id: u.id, days: per_day }
}

slots_nested = for d in days {
    for t in times {
        free_all = fold acc = true for u in per_user {
            busy = fold b_acc = [] for e in u.days {
                return e.busy if e.day == d else b_acc
            }
            conflict = fold c_acc = false for b in busy {
                ov = if b.start != null and b.end != null {
                    ps = text.split(b.start, ":")
                    pe = text.split(b.end, ":")
                    bs = number.parse(ps[0]) * 60 + number.parse(ps[1])
                    be = number.parse(pe[0]) * 60 + number.parse(pe[1])
                    return bs < t + 60 and be > t
                } else {
                    return false
                }
                return c_acc or ov
            }
            return acc and not conflict
        }
        skip if not free_all
        return { day: d, start: t }
    }
}

slots = fold acc = [] for row in slots_nested { return acc + row }
first = slots[0] if slots != [] else fail("NONE", "no valid slot found")

t = first.start
d = first.day
e = t + 60

sh = number.floor(t / 60)
sm = t - sh * 60
eh = number.floor(e / 60)
em = e - eh * 60

shs0 = json.encode(sh)
shs = if text.length(shs0) == 1 { return "0" + shs0 } else { return shs0 }
sms0 = json.encode(sm)
sms = if text.length(sms0) == 1 { return "0" + sms0 } else { return sms0 }
ehs0 = json.encode(eh)
ehs = if text.length(ehs0) == 1 { return "0" + ehs0 } else { return ehs0 }
ems0 = json.encode(em)
ems = if text.length(ems0) == 1 { return "0" + ems0 } else { return ems0 }

start_iso = d + "T" + shs + ":" + sms + ":00Z"
end_iso = d + "T" + ehs + ":" + ems + ":00Z"

submission = submit_result({ answer: { start: start_iso, end: end_iso } })
return { slot: { start: start_iso, end: end_iso }, submission: submission }

